style.css:
@-moz-document domain("pinterest.com") {
/* Fondo general */
  body, html, #APP_ROOT, .App, .Scaffold, .scaffoldContainer {
    background: url("https://userstyles.org/styles/181099/purple-bg.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Limpia fondos blancos en contenedores principales */
  div[data-test-id="simple-board-feed"],
  div[data-test-id="search-feed"],
  div[data-test-id="homefeed-feed"],
  .Grid, .Grid-scroller {
    background-color: transparent !important;
  }

  /* Pines/tarjetas transparentes con bordes */
  div[data-test-id="pin"], .GrowthUnauthPinImage {
    background-color: rgba(0, 0, 0, 0.5) !important;
    border-radius: 8px !important;
  }

  /* Header transparente con blur */
  header, .AppHeader, .HeaderContainer {
    background-color: rgba(0,0,0,0.4) !important;
    backdrop-filter: blur(8px) !important;
  }

  /* Barras laterales transparentes */
  .NavBar, .LeftNav, .RightNav, .modalContainer {
    background-color: rgba(0,0,0,0.3) !important;
  }

  /* Scrollbar personalizada */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-thumb {
    background: rgba(100,100,100,0.6);
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: rgba(150,150,150,0.8);
  }
}
